"""Merkle membership proof verifier."""

from hash_util import hash_leaf, hash_pair
from proof import MembershipProof


class MerkleProofVerifier:
    @staticmethod
    def verify(proof: MembershipProof, root_hash: str) -> bool:
        curr = hash_leaf(proof.leaf_data)
        for sibling, is_right in proof.audit_path:
            # BUG: Always hashes curr as left and sibling as right,
            # ignoring is_right boolean direction indicator!
            curr = hash_pair(curr, sibling)
        return curr == root_hash

repo_files.merkle_tree.py:
"""Binary Merkle tree construction and proof generator."""

from typing import List
from hash_util import hash_leaf, hash_pair
from proof import MembershipProof


class MerkleTree:
    def __init__(self, leaves: List[str]):
        self.leaves = list(leaves)
        self.layers: List[List[str]] = []
        self._build()

    def _build(self):
        curr = [hash_leaf(l) for l in self.leaves]
        self.layers.append(curr)
        while len(curr) > 1:
            if len(curr) % 2 != 0:
                curr.append(curr[-1])
            nxt = []
            for i in range(0, len(curr), 2):
                nxt.append(hash_pair(curr[i], curr[i + 1]))
            self.layers.append(nxt)
            curr = nxt

    @property
    def root(self) -> str:
        return self.layers[-1][0] if self.layers and self.layers[-1] else ""

    def generate_proof(self, index: int) -> MembershipProof:
        path = []
        idx = index
        for layer in self.layers[:-1]:
            is_right_child = (idx % 2 == 1)
            sibling_idx = idx - 1 if is_right_child else idx + 1
            if sibling_idx >= len(layer):
                sibling_idx = idx
            sibling_hash = layer[sibling_idx]
            # is_sibling_right is True if sibling is on the right
            path.append((sibling_hash, not is_right_child))
            idx //= 2
        return MembershipProof(self.leaves[index], index, path)

